  "歩": { kind: "ideographic", explanation: "An ideographic formation: Modern form of 歨; putting one foot 止 in front of the other.", note: "Formation data is recorded for the traditional form 步; 歩 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "向": { kind: "documented", explanation: "Depicts a mouth (口) in a closed space (宀) making an echo sound. Based on the original meaning \"echo; sound\", now written as 響. The current meaning is a phonetic loan.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
  "妹": { kind: "pictophonetic", explanation: "A phono-semantic character: 女 (woman) supplies the meaning element, while 未 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "辺": { kind: "pictophonetic", explanation: "A phono-semantic character: 辶 (walk) supplies the meaning element, while 臱 supplies the original sound element.", note: "Formation data is recorded for the traditional form 邊; 辺 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "付": { kind: "ideographic", explanation: "An ideographic formation: To hand 寸 something over to someone 亻.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "札": { kind: "structural", explanation: "The documented modern glyph structure is 木 + 乚 in a left–right arrangement. Structural decomposition alone does not establish historical origin.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "鳥": { kind: "pictographic", explanation: "A pictograph: A bird.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "黒": { kind: "ideographic", explanation: "An ideographic formation: A man's face blacked by soot from a fire 灬.", note: "Formation data is recorded for the traditional form 黑; 黒 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "船": { kind: "pictophonetic", explanation: "A phono-semantic character: 舟 (ship) supplies the meaning element. The source does not identify the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "必": { kind: "pictographic", explanation: "Pictograph of a weapon, now written as 柲. The current meaning is a phonetic loan.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
  "象": { kind: "pictophonetic", explanation: "A phono-semantic character: 豕 (boar) supplies the meaning element. The source does not identify the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "末": { kind: "ideographic", explanation: "An ideographic formation: The top 一 of a tree 木.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "氏": { kind: "ideographic", explanation: "An ideographic formation: A person bowing down.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "失": { kind: "ideographic", explanation: "An ideographic formation: Something 丿 falling from a hand 夫.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "魚": { kind: "pictographic", explanation: "A pictograph: A fish swimming upwards.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "床": { kind: "ideographic", explanation: "An ideographic formation: A house 广 made out of wood 木; 广 also provides the pronunciation.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "以": { kind: "uncertain", explanation: "Origin unclear. The right component is 人 (person).", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
  "組": { kind: "pictophonetic", explanation: "A phono-semantic character: 糹 (thread) supplies the meaning element, while 且 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "画": { kind: "ideographic", explanation: "An ideographic formation: To paint 聿 a canvas 田 on an easel 一.", note: "Formation data is recorded for the traditional form 畫; 画 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "欠": { kind: "pictophonetic", explanation: "A phono-semantic character: 缶 (jar) supplies the meaning element, while 夬 supplies the original sound element.", note: "Formation data is recorded for the traditional form 缺; 欠 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "未": { kind: "ideographic", explanation: "An ideographic formation: A wheat plant that has not yet borne fruit; compare 來.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "紙": { kind: "pictophonetic", explanation: "A phono-semantic character: 糹 (silk) supplies the meaning element, while 氏 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "通": { kind: "pictophonetic", explanation: "A phono-semantic character: 辶 (walk) supplies the meaning element, while 甬 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
