  "校": { kind: "pictophonetic", explanation: "A phono-semantic character: 木 (wood) supplies the meaning element, while 交 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "雪": { kind: "pictophonetic", explanation: "A phono-semantic character: 雨 (rain) supplies the meaning element, while 彐 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "南": { kind: "pictographic", explanation: "A pictograph: A musical bell.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "強": { kind: "pictophonetic", explanation: "A phono-semantic character: 弓 (bow) supplies the meaning element, while 虫 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "夏": { kind: "pictographic", explanation: "Pictograph of a person, represented by their head (頁) and feet (夂), being heated underneath the sun (日). The sun component was later omitted for brevity during the Warring States period.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
