  "求": { kind: "pictographic", explanation: "Pictograph of a crawling insect. The current meaning \"seek\" or \"beg\" is a phonetic loan.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
  "転": { kind: "pictophonetic", explanation: "A phono-semantic character: 車 (cart) supplies the meaning element, while 專 supplies the original sound element.", note: "Formation data is recorded for the traditional form 轉; 転 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "路": { kind: "pictophonetic", explanation: "A phono-semantic character: 足 (foot) supplies the meaning element, while 各 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
