  "解": { kind: "ideographic", explanation: "An ideographic formation: To cut 刀 the horns 角 off of an ox 牛; 角 also provides the pronunciation.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "歌": { kind: "pictophonetic", explanation: "A phono-semantic character: 欠 (breath) supplies the meaning element, while 哥 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "直": { kind: "ideographic", explanation: "An ideographic formation: To look someone in the eye 目.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "起": { kind: "pictophonetic", explanation: "A phono-semantic character: 走 (walk) supplies the meaning element, while 己 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "功": { kind: "ideographic", explanation: "An ideographic formation: Results produced by capable 力 labor 工; 工 also provides the pronunciation.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "成": { kind: "pictophonetic", explanation: "Phonosemantic compound. 戊 represents the meaning and 丁 represents the sound. The 戊 (axe) component is used to represent defending a city. Based on the original meaning \"city\", now written as 城. The meaning later shifted to \"build\", \"accomplish\", and \"complete\".", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
  "競": { kind: "ideographic", explanation: "An ideographic formation: Two people 竞 locked in a struggle.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "争": { kind: "ideographic", explanation: "An ideographic formation: Two hands 爪 and 彐 fighting over 亅.", note: "Formation data is recorded for the traditional form 爭; 争 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "便": { kind: "ideographic", explanation: "When uncomfortable, a person (亻) will change (更) to a more convenient (便) position.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
  "老": { kind: "pictographic", explanation: "A pictograph: A person bent over with long hair 匕 and a crutch; compare 耂.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "命": { kind: "ideographic", explanation: "An ideographic formation: An order 令 given by mouth 口.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
