  "的": { kind: "pictophonetic", explanation: "Phonosemantic compound. 白 represents the meaning and 勺 represents the sound. The character is based on the original meaning \"bright white\", which is unrelated to the modern meaning.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
