  "歴": { kind: "pictophonetic", explanation: "A phono-semantic character: 厤 (calendar) supplies the meaning element, while 止 supplies the original sound element.", note: "Formation data is recorded for the traditional form 歷; 歴 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
