  "団": { kind: "ideographic", explanation: "An ideographic formation: A lot of talent 專 gathered in one place 囗.", note: "Formation data is recorded for the traditional form 團; 団 is the modern Japanese form.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "史": { kind: "ideographic", explanation: "An ideographic formation: A hand 乂 using a pen to record a history.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
