  "善": { kind: "ideographic", explanation: "An ideographic formation: To give someone food 羊 and conversation 口.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
