  "宇": { kind: "pictophonetic", explanation: "A phono-semantic character: 宀 (building) supplies the meaning element, while 于 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "詞": { kind: "pictophonetic", explanation: "A phono-semantic character: 言 (words) supplies the meaning element, while 司 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
  "芋": { kind: "pictophonetic", explanation: "A phono-semantic character: 艹 (plant) supplies the meaning element, while 于 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
