  "若": { kind: "pictographic", explanation: "Pictograph of a person smoothing out their hair with their hands. Based on the original meaning \"smooth\". The meaning later shifted to \"obedient\" and \"conform to\". The 口 (mouth) component was added later when the character became more abstract.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
