  "尻": { kind: "pictophonetic", explanation: "A phono-semantic character: 尸 (body) supplies the meaning element. The source does not identify the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
