  "飛": { kind: "ideographic", explanation: "An ideographic formation: Two birds 飞 flying.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
