  "防": { kind: "pictophonetic", explanation: "A phono-semantic character: 阝 (wall) supplies the meaning element, while 方 supplies the original sound element.", source: { title: "Make Me a Hanzi", url: "https://github.com/skishore/makemeahanzi/blob/bddc96d41bef78427ed0e034e9f7e31d71fd1b92/dictionary.txt" } },
