  "粛": { kind: "ideographic", explanation: "The 𣶒 (deep; profound) component hints at the meaning. The purpose of the 聿 (writing utensil) component is unclear.", note: "Formation data is recorded for the traditional form 肅; 粛 is the modern Japanese form.", source: { title: "Chinese Lexicon", url: "https://github.com/peterolson/chinese-lexicon/tree/de64ca4c5d3fef6694a1270f943726c5f622bb03/etymology" } },
